update.foreach:
UPDATE so_b2c SET
approve_time = #{item.approveTime}, approve_user_id = #{item.approveUserId}, approve_user_name = #{item.approveUserName},
WHERE id = #{item.id}

mapper.select:
select sb2c.id, sb2c.code, sb2c.platform_code, sb2cr.receiver_name, sb2cr.first_address, sb2cr.second_address, sb2cr.full_address, sb2cd.id as detailId, sb2cd.image_url, sb2cd.sku_id, sb2cd.sku_no, sb2cd.platform_spu_no, sb2cd.platform_sku_no, sb2cl.weight, sb2cd.tax_cost, sb2cd.amount as sourceAmount, sb2c.currency as sourceCurrency, sb2cd.exchange_rate, sb2cd.qty, sb2cd.warehouse_id, sb2cd.warehouse_name, sb2cd.warehouse_location, sb2c.dict_platform, sb2c.shop_id , sb2cr.name as buyerName, sb2cl.logistics_channel_name, sb2cl.logistics_channel_id from so_b2c sb2c left outer join so_b2c_detail sb2cd on sb2c.id = sb2cd.main_id and sb2cd.is_deleted = false left outer join so_b2c_logistics sb2cl on sb2c.id = sb2cl.main_id and sb2cl.is_deleted = false left outer join so_b2c_receiver sb2cr on sb2c.id = sb2cr.main_id and sb2cr.is_deleted = false
sb2c.is_deleted = false and sb2c.invalid_status = false and sb2c.pay_status = 'paid' and sb2c.is_not_merge = false and (sb2c.approve_status = 'waitSubmit' or sb2c.approve_status = 'reject') and sb2c.label_json !~ 'AFN' and sb2cd.label_json !~ 'U_TAXED' and sb2cd.label_json !~ 'I_TAXED' and sb2cd.label_json !~ 'cainiaoInternationalWarehouse' and sb2c.dict_platform != 'Shopee' and sb2c.dict_platform != 'mercadolibre' and not exists (select id from so_b2c_ref where is_deleted = false and (target_id = sb2c.id or source_id = sb2c.id)) and exists (select main_id from so_b2c_detail where is_deleted = false and sb2c.id = main_id group by main_id having count(DISTINCT warehouse_id) = 1)
and sb2c.dict_platform in
#{item}
and sb2c.shop_id in
#{item}
and sb2c.currency in
#{item}
and sb2cr.name in
#{item}
and sb2cr.receiver_name in
#{item}
and sb2cr.first_address in
#{item}
and sb2cr.second_address in
#{item}
and sb2cr.full_address in
#{item}
and sb2cd.warehouse_id in
#{item}
and sb2cl.logistics_channel_id in
#{item}
and sb2c.shop_id in (select id from shop_info where is_deleted = false and disabled = false )
and sb2c.shop_id in (select shop_id from shop_sys_user_auth where is_deleted = false and user_id = #{shopAuthResultDTO.userId} )
order by sb2c.id desc

SELECT sb.dict_platform, sb.shop_id, sbd.platform_spu_no, COUNT ( sb.ID ) AS orderCount, SUM ( sbd.qty ) AS qty, ROUND( SUM ( sb.amount * sb.exchange_rate ), 2 ) AS amount FROM so_b2c sb LEFT JOIN so_b2c_detail sbd ON sb.ID = sbd.main_id AND sbd.is_deleted = FALSE WHERE sb.is_deleted = FALSE
AND (( sbd.sku_no ILIKE concat('%',#{params.skuNo}::text,'%') ) OR ( sbd.platform_sku_no ILIKE concat('%',#{params.skuNo}::text,'%') ) OR ( sbd.platform_spu_no ILIKE concat('%',#{params.skuNo}::text,'%') ))
AND sb.dict_platform IN
#{dictPlatform}
AND sbd.sku_id IN
#{skuId}
AND sb.shop_id IN
#{shopId}
AND sb.platform_order_create_time >= #{params.orderCreateTimeList[0]} AND sb. platform_order_create_time <= #{params.orderCreateTimeList[1]}
GROUP BY sb.dict_platform, sb.shop_id, sbd.platform_spu_no

SELECT sb.dict_platform, sb.shop_id, sbd.platform_spu_no, COUNT ( sb.ID ) AS orderCount, SUM ( sbd.qty ) AS qty, ROUND( SUM ( sb.amount * sb.exchange_rate ), 2 ) AS amount FROM so_b2c sb LEFT JOIN so_b2c_detail sbd ON sb.ID = sbd.main_id AND sbd.is_deleted = FALSE WHERE sb.is_deleted = FALSE
AND (( sbd.sku_no ILIKE concat('%',#{params.skuNo}::text,'%') ) OR ( sbd.platform_sku_no ILIKE concat('%',#{params.skuNo}::text,'%') ) OR ( sbd.platform_spu_no ILIKE concat('%',#{params.skuNo}::text,'%') ))
AND sb.dict_platform IN
#{dictPlatform}
AND sbd.sku_id IN
#{skuId}
AND sb.shop_id IN
#{shopId}
AND sb.platform_order_create_time >= #{params.orderCreateTimeList[0]} AND sb. platform_order_create_time <= #{params.orderCreateTimeList[1]}
GROUP BY sb.dict_platform, sb.shop_id, sbd.platform_spu_no

SELECT sb2c.id AS soId, sb2c.shop_id, sb2c.org_id AS salesOrgId, sb2c.org_name AS salesOrgName, si.name AS customerName, sb2r.country, sb2r.full_address AS receiverAddress, sb2r.tel_number AS telNumber, sb2r.receiver_name AS receiverName FROM so_b2c sb2c LEFT JOIN so_b2c_receiver sb2r ON sb2c.id = sb2r.main_id AND sb2r.is_deleted = FALSE LEFT JOIN shop_info si ON sb2c.shop_id = si.id AND si.is_deleted = FALSE WHERE sb2c.is_deleted = FALSE
AND sb2c.id IN
#{item}

SELECT sb2c.* FROM so_b2c sb2c INNER JOIN so_b2c_detail sb2cd ON sb2c.id = sb2cd.main_id AND sb2cd.is_deleted = false WHERE sb2cd.is_deleted=FALSE AND sb2cd.warehouse_id =''
AND sb2c.id IN
#{item}

SELECT sb.id AS soId, sb.code AS soCode, sbl.logistics_channel_id AS logisticsChannelId, sbl.code AS trackNo, sbl.weight AS packageWeight FROM so_b2c sb INNER JOIN so_b2c_logistics sbl ON sbl.main_id = sb.id AND sbl.is_deleted = FALSE WHERE sb.is_deleted = FALSE AND sb.transfer_status = 'wait' AND sb.package_status = 'not' AND sb.bill_status = 'waitShipped'
AND sbl.logistics_channel_id IN
#{channelId}

SELECT sb.id AS soId, sb.code AS soCode, sb.bill_status AS billStatus, sb.package_status AS packageStatus, sb.shop_id AS shopId, sbl.logistics_channel_id AS logisticsChannelId, sbl.code AS trackNo, sbl.track_no AS trackNo, sbl.weight AS weight, sbr.receiver_name AS receiverName, sbr.country_name AS countryName, sbr.country AS country, sbl.transfer_logistics_supplier_id, sbl.transfer_logistics_channel_id FROM so_b2c sb LEFT JOIN so_b2c_logistics sbl ON sb.id = sbl.main_id AND sbl.is_deleted = FALSE LEFT JOIN so_b2c_receiver sbr ON sb.id = sbr.main_id AND sbr.is_deleted = FALSE WHERE sb.is_deleted = FALSE AND sb.invalid_status = FALSE AND sb.is_intercept = FALSE
AND sb.bill_status IN
#{item}
AND sb.package_status IN
#{item}
AND sb.shop_id IN
#{item}
AND sbl.logistics_channel_id IN
#{item}
AND sbl.logistics_channel_name ILIKE CONCAT('%',#{params.logisticsChannelName}::text,'%')
ORDER BY sb.create_time DESC

SELECT sb.id AS soId, sb.code AS soCode, sb.bill_status AS billStatus, sb.package_status AS packageStatus, sb.shop_id AS shopId, sbl.logistics_channel_id AS logisticsChannelId, sbl.code AS transportNo, sbl.track_no AS trackNo, sbl.weight AS weight, sbl.transfer_logistics_supplier_id, sbl.transfer_logistics_channel_id, sb.dict_platform, sb.is_intercept as isIntercept FROM so_b2c sb LEFT JOIN so_b2c_logistics sbl ON sb.id = sbl.main_id AND sbl.is_deleted = FALSE WHERE sb.is_deleted = FALSE
AND sb.id IN
#{item}

SELECT T.code, T.dict_platform, h.NAME shop_name, G.sku_no, G.platform_sku_no FROM so_b2c T LEFT JOIN so_b2c_detail G ON T.ID = G.main_id LEFT JOIN shop_info h ON T.shop_id = h.ID WHERE T.is_deleted = 'f' AND G.is_deleted = 'f' AND H.is_deleted = 'f'
AND t.code IN
#{item}
AND T.dict_platform = #{params.dictPlatform}
AND h.name = #{params.shopName}

SELECT sb2c.id, sb2c.invalid_status as invalidStatus, sb2c.code as erpOrderCode, sb2c.platform_code as platformOrderCode, sb2c.seller_order_code as sellerOrderCode, sb2c.source_type as orderSource, sb2c.bill_status as orderStatus, sb2c.approve_status as approveStatus, sbd.code as deliveryCode, sbl.logistics_channel_id as logisticChannelId, sbl.code as transportCode, sbl.track_no as trackingNumber, sb2c.approve_time as approveTime, sout.bill_date as deliveryDate from so_b2c sb2c inner join so_b2c_logistics sbl on sb2c.id = sbl.main_id and sbl.is_deleted = false left join so_outstock sout on sout.so_id = sb2c.id and sout.is_deleted = false left join so_b2c_delivery sbd on sbd.source_id = sb2c.id and sbd.is_deleted = false where sb2c.is_deleted = false and sb2c.shop_id = #{params.erpShopId}
and sb2c.platform_code in
#{item}
and sb2c.seller_order_code in
#{item}
AND sb2c.bill_status = #{params.orderStatus}
AND sb2c.approve_status = #{params.approveStatus}
and sout.bill_date >= #{params.deliveryStartTime}
and sout.bill_date <= #{params.deliveryEndTime}
order by sb2c.id desc
